package kit

import (
	"context"
	"os"
	"path/filepath"
	"testing"
	"time"
)

// Approval is supplied by the caller after review, never generated by the producer.
func TestQuerySemanticsJSONVerify(t *testing.T) {
	if os.Getenv("TSGK_QUERY_JSON_LOCAL_STAGE") != "verify" {
		t.Skip("explicit local assembled input is required")
	}
	root := os.Getenv("TSGK_QUERY_JSON_ASSEMBLY")
	if !filepath.IsAbs(root) {
		t.Fatal("absolute assembly root required")
	}
	caller := filepath.Join(root, "caller")
	out, err := os.MkdirTemp(root, "verification-")
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("verification_root=%q", out)
	read := func(name string) []byte { return actualJSONRead(t, filepath.Join(caller, name)) }
	req := QuerySemanticsRequest{Evidence: EvidenceRequest{Root: filepath.Join(root, "evidence"), Policy: read("policy.json")}, Profile: read("profile.json"), Registration: read("semantic-registration.json")}
	var reg eligibilityRegistration
	actualJSONDecode(t, filepath.Join(caller, "eligibility-registration.json"), &reg)
	var members []semanticBoundMember
	actualJSONDecode(t, filepath.Join(caller, "binding-members.json"), &members)
	binding := semanticRunBinding{Schema: "tsgk-query-semantics-run-binding/r1", ProfileSHA256: digestHex(req.Profile), ManifestSHA256: digestHex(actualJSONRead(t, filepath.Join(req.Evidence.Root, "oracle", "manifest.json"))), RegistrationSHA256: digestHex(req.Registration), EligibilityApprovalSHA256: digestHex(nil), EligibilityRegistrationSHA256: digestHex(nil), WitnessRegistrationSHA256: digestHex(nil), EvidencePolicySHA256: digestHex(req.Evidence.Policy), EvidenceSHA256: reg.Graph.SHA256, DriverNode: "native-c1", OracleNode: "oracle-json24", References: []semanticReferenceBinding{}, Members: members}
	req.RunBinding = eligibilityJSON(t, binding)
	ctx, cancel := context.WithTimeout(context.Background(), 120*time.Second)
	defer cancel()
	absent, err := VerifyQuerySemantics(ctx, req)
	actualJSONWrite(t, filepath.Join(out, "absent-result.json"), eligibilityJSON(t, absent))
	if err != nil || !absent.Complete || absent.Assessment != AssessBlocked || absent.BaseVerified.Assessment != AssessPass || absent.Tuple != (QueryEligibilityCounts{Required: 24, Blocked: 24}) {
		t.Fatalf("actual absent approval: %v code=%s findings=%+v", err, absent.Code, absent.Findings)
	}
	approvalPath := os.Getenv("TSGK_QUERY_JSON_APPROVAL")
	if approvalPath == "" {
		t.Log("actual bytes without approval: base PASS, 24 BLOCKED; no approval supplied")
		return
	}
	if !filepath.IsAbs(approvalPath) {
		t.Fatal("absolute independently reviewed approval required")
	}
	req.EligibilityApproval = actualJSONRead(t, approvalPath)
	req.EligibilityRegistration, req.WitnessRegistration = read("eligibility-registration.json"), read("witness.json")
	binding.EligibilityApprovalSHA256, binding.EligibilityRegistrationSHA256, binding.WitnessRegistrationSHA256 = digestHex(req.EligibilityApproval), digestHex(req.EligibilityRegistration), digestHex(req.WitnessRegistration)
	binding.CohortID, binding.InvocationID = "current", "native-c1"
	for _, inv := range reg.Invocations {
		if inv.ID == binding.InvocationID && inv.Process != nil {
			binding.Process = *inv.Process
		}
	}
	actualJSONDecode(t, filepath.Join(caller, "reference-bindings.json"), &binding.References)
	req.RunBinding = eligibilityJSON(t, binding)
	actualJSONWrite(t, filepath.Join(out, "run-binding.json"), req.RunBinding)
	passed, err := VerifyQuerySemantics(ctx, req)
	actualJSONWrite(t, filepath.Join(out, "api-result.json"), eligibilityJSON(t, passed))
	checkCounts := func(r QuerySemanticsResult) {
		t.Helper()
		if !r.Complete || !r.BindingValid || r.Semantic != AssessPass || r.BaseVerified != (Verdict{StatusCompleted, AssessPass}) || r.ProducerRecorded != (Verdict{StatusCompleted, AssessBlocked}) || r.Eligibility == nil || !r.Eligibility.Complete {
			t.Fatal("incomplete actual semantic result", r.Code)
		}
		for _, count := range []struct {
			got      QueryEligibilityCounts
			required uint64
		}{{r.Eligibility.Build, 9}, {r.Eligibility.Unit, 4}, {r.Eligibility.Control, 53}, {r.Eligibility.Assertion, 36}, {r.Eligibility.Tuple, 24}, {r.Tuple, 24}} {
			if count.got != (QueryEligibilityCounts{Required: count.required, Verified: count.required}) {
				t.Fatalf("actual denominator not fully verified: %+v expected %d", count.got, count.required)
			}
		}
	}
	if err != nil || !passed.Complete || passed.Assessment != AssessPass || !passed.BindingValid || passed.Semantic != AssessPass || passed.BaseVerified.Assessment != AssessPass || passed.Tuple != (QueryEligibilityCounts{Required: 24, Verified: 24}) || passed.ProducerRecorded != (Verdict{StatusCompleted, AssessBlocked}) || passed.Eligibility == nil || passed.Eligibility.Assessment != AssessPass {
		t.Fatalf("actual caller-bound API: %v code=%s findings=%+v eligibility=%+v", err, passed.Code, passed.Findings, passed.Eligibility)
	}
	checkCounts(passed)
	replayRoot := filepath.Join(out, "replay")
	if err := os.MkdirAll(filepath.Join(replayRoot, "evidence"), 0700); err != nil {
		t.Fatal(err)
	}
	replayMembers := []ReplayMember{}
	for _, doc := range []struct {
		path, role string
		data       []byte
	}{
		{"profile.json", "workload-profile", req.Profile}, {"registration.json", "semantics-registration", req.Registration}, {"binding.json", "semantics-run-binding", req.RunBinding}, {"approval.json", "eligibility-approval", req.EligibilityApproval}, {"eligibility.json", "eligibility-registration", req.EligibilityRegistration}, {"witness.json", "query-registration", req.WitnessRegistration}, {"policy.json", "evidence-policy", req.Evidence.Policy},
	} {
		actualJSONWrite(t, filepath.Join(replayRoot, doc.path), doc.data)
		replayMembers = append(replayMembers, ReplayMember{Path: doc.path, Role: doc.role, Bytes: uint64(len(doc.data)), SHA256: digestHex(doc.data)})
	}
	pins := []ReplayMember{reg.Graph}
	for _, owned := range reg.OwnedMembers {
		pins = append(pins, owned.Member)
	}
	for _, pin := range pins {
		data := actualJSONRead(t, filepath.Join(req.Evidence.Root, filepath.FromSlash(pin.Path)))
		if uint64(len(data)) != pin.Bytes || digestHex(data) != pin.SHA256 {
			t.Fatal("changed evidence", pin.Path)
		}
		path := filepath.Join(replayRoot, "evidence", filepath.FromSlash(pin.Path))
		if err := os.MkdirAll(filepath.Dir(path), 0700); err != nil {
			t.Fatal(err)
		}
		actualJSONWrite(t, path, data)
		pin.Path = "evidence/" + pin.Path
		pin.Role = "semantics-evidence"
		replayMembers = append(replayMembers, pin)
	}
	var approval eligibilityApproval
	actualJSONDecode(t, approvalPath, &approval)
	profile := eligibilityJSON(t, map[string]any{"schema": ReplaySchema, "id": "actual-json24-replay", "reducer": "oracle-set-r4", "operation": "evidence-replay", "subject": ReplaySubject{Run: approval.Candidate.Run, Attempt: 1, Platform: "windows/amd64", EvidenceMode: ModeNewRun, ExecutionStatus: StatusCompleted, Assessment: AssessBlocked}, "identities": map[string]string{"workload": digestHex(req.Profile), "semantics-registration": digestHex(req.Registration), "semantics-run-binding": digestHex(req.RunBinding), "evidence-policy": digestHex(req.Evidence.Policy)}, "records": []string{"c1"}, "members": replayMembers})
	actualJSONWrite(t, filepath.Join(out, "replay-profile.json"), profile)
	replayed, err := Replay(ctx, ReplayRequest{Root: replayRoot, Profile: profile})
	actualJSONWrite(t, filepath.Join(out, "replay-result.json"), eligibilityJSON(t, replayed))
	if err != nil || replayed.Assessment != AssessPass || !replayed.EvidenceValid || replayed.QuerySemantics == nil || replayed.QuerySemantics.Tuple != passed.Tuple || replayed.QuerySemantics.ProducerRecorded != passed.ProducerRecorded || !validSemanticReplayResult(replayed) || replayed.BytesRead != passed.BytesRead {
		t.Fatalf("actual same-byte replay: %v findings=%+v APIbytes=%d replaybytes=%d", err, replayed.Findings, passed.BytesRead, replayed.BytesRead)
	}
	checkCounts(*replayed.QuerySemantics)
	apiDigest := [8]string{passed.ProfileSHA256, passed.RegistrationSHA256, passed.RunBindingSHA256, passed.Eligibility.ApprovalSHA256, passed.Eligibility.RegistrationSHA256, passed.Eligibility.WitnessSHA256, passed.Eligibility.CatalogueSHA256, passed.Eligibility.GraphSHA256}
	replayCore := replayed.QuerySemantics
	replayDigest := [8]string{replayCore.ProfileSHA256, replayCore.RegistrationSHA256, replayCore.RunBindingSHA256, replayCore.Eligibility.ApprovalSHA256, replayCore.Eligibility.RegistrationSHA256, replayCore.Eligibility.WitnessSHA256, replayCore.Eligibility.CatalogueSHA256, replayCore.Eligibility.GraphSHA256}
	if apiDigest != replayDigest {
		t.Fatal("API/replay digest mismatch")
	}
	for _, name := range []string{"owner", "slice"} {
		negative := req
		switch name {
		case "owner":
			changed := binding
			changed.DriverNode = "oracle-json24"
			negative.RunBinding = eligibilityJSON(t, changed)
		case "slice":
			var changed eligibilityRegistration
			actualJSONDecode(t, filepath.Join(caller, "eligibility-registration.json"), &changed)
			changed.Observations[0].ByteLength++
			negative.EligibilityRegistration = eligibilityJSON(t, changed)
			var trusted eligibilityApproval
			actualJSONDecode(t, approvalPath, &trusted)
			trusted.RegistrationSHA256 = digestHex(negative.EligibilityRegistration)
			negative.EligibilityApproval = eligibilityJSON(t, trusted)
			changedBinding := binding
			changedBinding.EligibilityRegistrationSHA256 = digestHex(negative.EligibilityRegistration)
			changedBinding.EligibilityApprovalSHA256 = digestHex(negative.EligibilityApproval)
			negative.RunBinding = eligibilityJSON(t, changedBinding)
		}
		result, e := VerifyQuerySemantics(ctx, negative)
		actualJSONWrite(t, filepath.Join(out, "negative-"+name+".json"), eligibilityJSON(t, result))
		if e != nil || !result.Complete || result.Assessment != AssessFail {
			t.Fatalf("actual negative %s: %v code=%s findings=%+v", name, e, result.Code, result.Findings)
		}
		want := "SEMANTICS_BINDING_GRAPH"
		if name == "slice" {
			want = "ELIGIBILITY_OBSERVATION_SLICE"
		}
		found := false
		for _, f := range result.Findings {
			if f.Code == want {
				found = true
			}
		}
		if result.Eligibility != nil {
			for _, f := range result.Eligibility.Findings {
				if f.Code == want {
					found = true
				}
			}
		}
		if !found {
			t.Fatalf("negative %s lacks expected %s", name, want)
		}
	}
	t.Log("actual JSON24: absent BLOCKED; caller-bound API/replay PASS; owner/slice FAIL; producer remains BLOCKED")
}
